INSERT INTO company_alerts (company_id, severity, title, message, blocks_action, locked, created_by_name) SELECT 'ea4a443c-a351-4243-ae00-e7d70f126d5a', 'CRITICAL', 'LM NÃO PODE GERAR ECF antes de regularizar as DIMOBs 2023, 2024 e 2025', 'Desde 13/11/2026 10:34:24 a última declaração apresentada é a ECF 2022 (Lucro Presumido), o que sustenta a faixa de R$ 500/mês da multa das DIMOBs em atraso (MP 2.158-35, art. 57, I, "a"). Uma ECF de Lucro Real (original ou retificadora de 2023-2025) transmitida antes delas move a faixa para R$ 1.500/mês - diferença estimada de R$ 32.000. DIMOB 2021 fora do escopo (decisão de 10/11/2026).', 'ECF_EXPORT', true, 'Hpontes' WHERE NOT EXISTS (SELECT 1 FROM company_alerts WHERE company_id = 'ea4a443c-a351-4243-ae00-e7d70f126d5a' AND title = 'LM NÃO PODE GERAR ECF antes de regularizar as DIMOBs 2023, 2024 e 2025');
INSERT INTO company_alerts (company_id, severity, title, message, blocks_action, locked, created_by_name) SELECT 'ea4a443c-a351-4243-ae00-e7d70f126d5a', 'WARNING', 'EFD-Contribuições dez/2023 declara 2023 inteiro sem receita', 'A DIMOB 2023 (a entregar até 30/11/2026) informará aluguéis recebidos em 2023. Retificar a EFD dez/2023 e entregar jan-nov/2023 por iniciativa própria, antes de qualquer procedimento de ofício (R3 e R4).', NULL, false, 'Hpontes' WHERE NOT EXISTS (SELECT 1 FROM company_alerts WHERE company_id = 'ea4a443c-a351-4243-ae00-e7d70f126d5a' AND title = 'EFD-Contribuições dez/2023 declara 2023 inteiro sem receita');
